// One row per Google Ads keyword (the Actor nests them in topKeywords). Sites without data or without ads are skipped.
const date = new Date().toISOString().slice(0, 10);
const out = [];
for (const { json: d } of $input.all()) {
  if (d.found === false) continue;
  for (const k of d.topKeywords || []) {
    out.push({ json: {
      date, domain: d.domain, keyword: k.keyword, adPosition: k.position, landingPage: k.url,
      adTitle: k.adTitle ?? null, adText: k.adDescription ?? null,
      estimatedClicks: k.estimatedTraffic == null ? null : Math.round(k.estimatedTraffic),
      searchVolume: k.searchVolume ?? null, cpcUsd: k.cpcUsd ?? null,
      siteMonthlyAdSpendUsd: d.paidTrafficCostUsd ?? null, country: d.country,
    } });
  }
}
return out;
